import mechanize
from bs4 import BeautifulSoup

def task_func(url, form_id, data):
    try:
        br = mechanize.Browser()
        br.open(url)

        target_form = None
        for form in br.forms():
            if getattr(form, "attrs", {}).get("id") == form_id:
                target_form = form
                break

        if target_form is None:
            return "No Title"

        br.form = target_form

        for key, value in (data or {}).items():
            try:
                br[key] = value
            except Exception:
                try:
                    control = br.form.find_control(name=key)
                    control.value = value
                except Exception:
                    pass

        response = br.submit()
        html = response.read()

        soup = BeautifulSoup(html, "html.parser")
        title_tag = soup.title
        title = title_tag.get_text(strip=True) if title_tag else ""

        return title if title else "No Title"
    except Exception:
        return "No Title"
